<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h3 mb-1">Selamat datang, <?= esc($user['name'] ?? 'Pengguna') ?></h1><p class="text-secondary mb-0">Ringkasan penyimpanan cloud Anda.</p></div><a class="btn btn-primary" href="/files">Kelola file</a></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="stat-card"><span class="text-secondary">Penyimpanan digunakan</span><div class="fs-3 fw-semibold"><?= number_format(((int)($user['used_bytes']??0))/1073741824,2) ?> GB</div><div class="progress mt-2"><div class="progress-bar" style="width:<?= min(100,round((int)($user['used_bytes']??0)/max(1,(int)($user['quota_bytes']??1))*100)) ?>%"></div></div><small class="text-secondary"><?= number_format(((int)($user['quota_bytes']??0))/1073741824,1) ?> GB kuota</small></div></div><div class="col-md-4"><div class="stat-card"><span class="text-secondary">Akun</span><div class="fs-3 fw-semibold"><?= esc(ucfirst($user['role']??'user')) ?></div></div></div><div class="col-md-4"><div class="stat-card"><span class="text-secondary">File terbaru</span><div class="fs-3 fw-semibold"><?= count($files) ?></div></div></div></div><div class="card p-3"><h2 class="h5 mb-3">File terbaru</h2><?php if(!$files): ?><p class="text-secondary mb-0">Belum ada file.</p><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nama file</th><th>Ukuran</th><th>Tanggal</th></tr></thead><tbody><?php foreach($files as $f): ?><tr><td><?= esc($f['original_name']) ?></td><td><?= number_format($f['size_bytes']/1048576,2) ?> MB</td><td><?= esc($f['created_at']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></div><?= $this->endSection() ?>
